31	// widening Theme to any so that the consumer can own the theme structure.
32	const defaultCreateStyledComponent = (systemStyled as CreateMUIStyled<any>)('div', {
33	  name: 'MuiGrid',
34	  slot: 'Root',
35	  overridesResolver: (props, styles) => styles.root,
