46	export default function createGrid(
47	  options: {
48	    createStyledComponent?: typeof defaultCreateStyledComponent;
49	    useThemeProps?: typeof useThemePropsDefault;
50	    useTheme?: typeof useThemeSystem;
51	    componentName?: string;
52	  } = {},
53	) {
54	  const {
55	    // This will allow adding custom styled fn (for example for custom sx style function)
56	    createStyledComponent = defaultCreateStyledComponent,
57	    useThemeProps = useThemePropsDefault,
58	    useTheme = useThemeSystem,
59	    componentName = 'MuiGrid',
60	  } = options;
61	
62	  const useUtilityClasses = (ownerState: GridOwnerState, theme: typeof defaultTheme) => {
63	    const { container, direction, spacing, wrap, size } = ownerState;
64	    const slots = {
65	      root: [
66	        'root',
67	        container && 'container',
68	        wrap !== 'wrap' && `wrap-xs-${String(wrap)}`,
69	        ...generateDirectionClasses(direction),
70	        ...generateSizeClassNames(size),
71	        ...(container ? generateSpacingClassNames(spacing, theme.breakpoints.keys[0]) : []),
72	      ],
73	    };
74	
75	    return composeClasses(slots, (slot) => generateUtilityClass(componentName, slot), {});
76	  };
77	
78	  function parseResponsiveProp<T extends GridSize | GridOffset>(
79	    propValue: T | null | (T | null)[] | { [key in Breakpoint]?: T | null },
80	    breakpoints: Breakpoints,
81	    shouldUseValue: (val: T) => boolean = () => true,
82	  ): { [key in Breakpoint]: T } {
83	    const parsedProp = {} as { [key in Breakpoint]: T };
84	
85	    if (propValue === null) {
86	      return parsedProp;
87	    }
88	
89	    if (Array.isArray(propValue)) {
90	      propValue.forEach((value, index) => {
91	        if (value !== null && shouldUseValue(value) && breakpoints.keys[index]) {
92	          parsedProp[breakpoints.keys[index]] = value;
93	        }
94	      });
95	    } else if (typeof propValue === 'object') {
96	      Object.keys(propValue).forEach((key) => {
97	        const value = propValue[key as Breakpoint];
98	        if (value !== null && value !== undefined && shouldUseValue(value)) {
99	          parsedProp[key as Breakpoint] = value;
100	        }
101	      });
102	    } else {
103	      parsedProp[breakpoints.keys[0]] = propValue;
104	    }
105	
106	    return parsedProp;
107	  }
108	
109	  const GridRoot = createStyledComponent<{
110	    ownerState: GridOwnerState;
111	  }>(
112	    generateGridColumnsStyles,
113	    generateGridColumnSpacingStyles,
114	    generateGridRowSpacingStyles,
115	    generateGridSizeStyles,
116	    generateGridDirectionStyles,
117	    generateGridStyles,
118	    generateGridOffsetStyles,
119	  );
120	
121	  const Grid = React.forwardRef(function Grid(inProps, ref) {
122	    const theme = useTheme();
123	    const themeProps = useThemeProps<typeof inProps & { component?: React.ElementType }>(inProps);
124	    const props = extendSxProp(themeProps) as Omit<typeof themeProps, 'color'> & GridOwnerState; // `color` type conflicts with html color attribute.
125	    const {
126	      className,
127	      children,
128	      columns: columnsProp = 12,
129	      container = false,
130	      component = 'div',
131	      direction = 'row',
132	      wrap = 'wrap',
133	      size: sizeProp = {},
134	      offset: offsetProp = {},
135	      spacing: spacingProp = 0,
136	      rowSpacing: rowSpacingProp = spacingProp,
137	      columnSpacing: columnSpacingProp = spacingProp,
138	      unstable_level: level = 0,
139	      ...other
140	    } = props;
141	    const size = parseResponsiveProp<GridSize>(sizeProp, theme.breakpoints, (val) => val !== false);
142	    const offset = parseResponsiveProp<GridOffset>(offsetProp, theme.breakpoints);
143	
144	    const columns = inProps.columns ?? (level ? undefined : columnsProp);
145	    const spacing = inProps.spacing ?? (level ? undefined : spacingProp);
146	    const rowSpacing =
147	      inProps.rowSpacing ?? inProps.spacing ?? (level ? undefined : rowSpacingProp);
148	    const columnSpacing =
149	      inProps.columnSpacing ?? inProps.spacing ?? (level ? undefined : columnSpacingProp);
150	    const ownerState = {
151	      ...props,
152	      level,
153	      columns,
154	      container,
155	      direction,
156	      wrap,
157	      spacing,
158	      rowSpacing,
159	      columnSpacing,
160	      size,
161	      offset,
162	    };
163	
164	    const classes = useUtilityClasses(ownerState, theme);
165	
166	    return (
167	      <GridRoot
168	        ref={ref}
169	        as={component}
170	        ownerState={ownerState}
171	        className={clsx(classes.root, className)}
172	        {...other}
173	      >
174	        {React.Children.map(children, (child) => {
175	          if (
176	            React.isValidElement<{ container?: unknown }>(child) &&
177	            isMuiElement(child, ['Grid']) &&
178	            container &&
179	            child.props.container
180	          ) {
181	            return React.cloneElement(child, {
182	              unstable_level: (child.props as GridProps)?.unstable_level ?? level + 1,
183	            } as GridProps);
184	          }
185	          return child;
186	        })}
187	      </GridRoot>
188	    );
189	  }) as OverridableComponent<GridTypeMap>;
190	
